// ============================================================
// PARSE FORM — extract Sheet ID + basic form fields
// Lightweight: just parsing, no lookups yet
// ============================================================
const form = $input.first().json;

const brandName = (form['Brand Name'] || '').trim();
if (!brandName) throw new Error('Brand Name is required.');

const sheetUrl = form['Data Sheet URL (Google Sheets)'] || '';
const sheetIdMatch = sheetUrl.match(/\/d\/([a-zA-Z0-9_-]+)/);
const sheetId = sheetIdMatch ? sheetIdMatch[1] : '';
if (!sheetId) throw new Error('Invalid Google Sheet URL.');

const now = new Date();
const y1ago = new Date(now);
y1ago.setFullYear(y1ago.getFullYear() - 1);

return [{ json: {
  _brand_name: brandName,
  _brand_key: brandName.toLowerCase(),
  _vat_rate: parseFloat(form['VAT Rate']) || 0.23,
  _default_margin: parseFloat(form['Default Margin']) || 0.10,
  _feed_url: (form['Feed URL (XML)'] || '').trim(),
  _sheet_id: sheetId,
  _date_from: (form['Date From (YYYY-MM-DD)'] || '').trim() || y1ago.toISOString().split('T')[0],
  _date_to: (form['Date To (YYYY-MM-DD)'] || '').trim() || now.toISOString().split('T')[0],
  _form_ga4_id: (form['GA4 Property ID (opcjonalne)'] || '').trim(),
  _form_meta_id: (form['Meta Account ID (opcjonalne)'] || '').trim()
} }];

// ============================================================
// BUILD CONFIG v8 — Merge: hardcoded + sheet history + form
// Priority: Form override > Sheet history > Hardcoded lookup
// ============================================================

const formData = $node['Parse Form'].json;

// --- HARDCODED KNOWN BRANDS ---
const HARDCODED = {
  'iiyama':      { ga4: '280127077',  meta: 'act_1438113836305522' },
  'bushido':     { ga4: '297192186',  meta: 'act_1930400651212132' },
  'koszulkowy':  { ga4: '270928705',  meta: 'act_1897121353740892' },
  'mindlink':    { ga4: '477769901',  meta: 'act_1578563932814949' }
};

// --- SHEET HISTORY (from brand_config tab) ---
const sheetBrands = $input.all().map(i => i.json);
const sheetMatch = sheetBrands.find(row =>
  (row.brand_name || '').toLowerCase().trim() === formData._brand_key
);

// --- RESOLUTION CASCADE: form > sheet > hardcoded > error ---
const hardcoded = HARDCODED[formData._brand_key];
const ga4Id = formData._form_ga4_id
           || (sheetMatch ? (sheetMatch.ga4_property_id || '') : '')
           || (hardcoded ? hardcoded.ga4 : '');
const metaId = formData._form_meta_id
            || (sheetMatch ? (sheetMatch.meta_account_id || '') : '')
            || (hardcoded ? hardcoded.meta : '');

if (!ga4Id) throw new Error(`GA4 Property ID missing for brand "${formData._brand_name}". Fill the optional field.`);
if (!metaId) throw new Error(`Meta Account ID missing for brand "${formData._brand_name}". Fill the optional field.`);

// Is this a genuinely new brand (not in hardcoded AND not in sheet)?
const isNewBrand = !hardcoded && !sheetMatch;

return [{ json: {
  BRAND: formData._brand_name,
  VAT_RATE: formData._vat_rate,
  DEFAULT_MARGIN: formData._default_margin,
  FEED_URL: formData._feed_url,
  SHEET_ID: formData._sheet_id,
  GA4_PROPERTY_ID: ga4Id,
  META_ACCOUNT_ID: metaId,
  DATE_FROM: formData._date_from,
  DATE_TO: formData._date_to,
  MSC_ALGO: { MIN_META_TRANS: 10, MIN_ORGANIC_SESSIONS: 300 },
  _is_new_brand: isNewBrand,
  _config_version: '8.0',
  _generated_at: new Date().toISOString()
} }];

// ============================================================
// MARGIN RESOLVER v8 — GATE NODE
// All downstream nodes branch from here.
// ============================================================

const rules = $input.all().map(item => ({
  match_type:  (item.json.match_type  || '').toUpperCase().trim(),
  match_value: (item.json.match_value || '').trim(),
  margin_rate: parseFloat(item.json.margin_rate) || 0,
  note:        item.json.note || ''
}));

const validTypes = ['SKU_EXACT', 'CATEGORY_EXACT', 'KEYWORD'];
const validRules = rules.filter(r => validTypes.includes(r.match_type) && r.margin_rate > 0);
const order = { 'SKU_EXACT': 1, 'CATEGORY_EXACT': 2, 'KEYWORD': 3 };
validRules.sort((a, b) => (order[a.match_type] || 99) - (order[b.match_type] || 99));

const config = $node['Build Config'].json;

return [{ json: {
  ...config,
  MARGIN_RULES: validRules,
  MARGIN_RULES_COUNT: validRules.length,
  _resolver_executed: true
} }];

// NORMALIZE FEED + RESOLVE MARGINS (4-Tier MECE)
const config = $node['Margin Resolver'].json;
const marginRules = config.MARGIN_RULES || [];
const defaultMargin = config.DEFAULT_MARGIN || 0.10;

function normalizeUrl(url) {
  if (!url) return '';
  return url.toLowerCase().replace(/^https?:\/\/(www\.)?/, '').split('?')[0].replace(/\/$/, '');
}

function resolveMargin(feedId, feedCategory) {
  const id = (feedId || '').trim();
  const cat = (feedCategory || '').toLowerCase().trim();
  for (const rule of marginRules) {
    const val = rule.match_value;
    switch (rule.match_type) {
      case 'SKU_EXACT':      if (id === val) return { rate: rule.margin_rate, rule: `SKU:${val}` }; break;
      case 'CATEGORY_EXACT': if (cat === val.toLowerCase()) return { rate: rule.margin_rate, rule: `CAT:${val}` }; break;
      case 'KEYWORD':        if (cat.includes(val.toLowerCase())) return { rate: rule.margin_rate, rule: `KW:${val}` }; break;
    }
  }
  return { rate: defaultMargin, rule: 'DEFAULT' };
}

const feedData = $input.first().json;
let products = [];
if (feedData.rss?.channel?.item) {
  products = Array.isArray(feedData.rss.channel.item) ? feedData.rss.channel.item : [feedData.rss.channel.item];
} else if (feedData.products?.product) {
  products = Array.isArray(feedData.products.product) ? feedData.products.product : [feedData.products.product];
}

return products.map(p => {
  const id = p.g_id || p.id || '';
  const cat = p.g_google_product_category || p.google_product_category || p.product_type || '';
  const { rate, rule } = resolveMargin(id, cat);
  return { json: {
    feed_id: id,
    feed_title: p.g_title || p.title || '',
    feed_brand: p.g_brand || p.brand || '',
    feed_category: cat,
    feed_link: p.g_link || p.link || '',
    norm_url: normalizeUrl(p.g_link || p.link),
    feed_price_numeric: parseFloat((p.g_price || p.price || '0').toString().replace(/[^0-9.]/g, '')) || 0,
    base_gross_margin: rate,
    margin_matched_rule: rule,
    _brand: config.BRAND,
    _vat_rate: config.VAT_RATE
  }};
});

// NORMALIZE GA4 LP RESPONSE
const response = $input.first().json;
const rows = response.rows || [];
return rows.map(row => {
  const dims = row.dimensionValues || [];
  const metrics = row.metricValues || [];
  const lp = dims[0]?.value || '';
  return { json: {
    ga4_landing_page: lp,
    ga4_norm_url: lp.toLowerCase().replace(/^\//, '').split('?')[0].replace(/\/$/, ''),
    ga4lp_sessions: parseInt(metrics[0]?.value || '0'),
    ga4lp_revenue: parseFloat(metrics[1]?.value || '0'),
    ga4lp_transactions: parseInt(metrics[2]?.value || '0')
  }};
});

// NORMALIZE GA4 ITEMS RESPONSE
const response = $input.first().json;
const rows = response.rows || [];
return rows.map(row => {
  const dims = row.dimensionValues || [];
  const metrics = row.metricValues || [];
  return { json: {
    ga4_item_id: dims[0]?.value || '',
    ga4item_views: parseInt(metrics[0]?.value || '0'),
    ga4item_revenue: parseFloat(metrics[1]?.value || '0'),
    ga4item_purchases: parseInt(metrics[2]?.value || '0')
  }};
});

// NORMALIZE META ADS RESPONSE
const response = $input.first().json;
const data = response.data || [];
function extractAction(actions, type) {
  if (!Array.isArray(actions)) return 0;
  const match = actions.find(a => a.action_type === type);
  return match ? parseFloat(match.value) : 0;
}
return data.map(ad => {
  const purchases = extractAction(ad.actions, 'offsite_conversion.fb_pixel_purchase') || extractAction(ad.actions, 'purchase');
  const purchaseValue = extractAction(ad.action_values, 'offsite_conversion.fb_pixel_purchase') || extractAction(ad.action_values, 'purchase');
  const spend = parseFloat(ad.spend || '0');
  return { json: {
    meta_ad_id: ad.ad_id || '',
    meta_ad_name: ad.ad_name || '',
    meta_spend: spend,
    meta_purchases: purchases,
    meta_purchase_value: purchaseValue,
    meta_roas: spend > 0 ? purchaseValue / spend : 0,
    meta_impressions: parseInt(ad.impressions || '0'),
    meta_clicks: parseInt(ad.clicks || '0'),
    meta_reach: parseInt(ad.reach || '0'),
    meta_cpc: parseFloat(ad.cpc || '0'),
    meta_cpm: parseFloat(ad.cpm || '0')
  }};
});

// ============================================================
// SAVE BRAND CONFIG — fires only for new brands
// Returns empty array (stops chain) if brand already known.
// ============================================================

const config = $node['Margin Resolver'].json;

if (!config._is_new_brand) {
  // Known brand — nothing to save, stop this branch
  return [];
}

// New brand: output a row for Google Sheets Append
return [{ json: {
  brand_name: config.BRAND,
  ga4_property_id: config.GA4_PROPERTY_ID,
  meta_account_id: config.META_ACCOUNT_ID,
  vat_rate: config.VAT_RATE,
  default_margin: config.DEFAULT_MARGIN,
  feed_url: config.FEED_URL,
  created_at: new Date().toISOString()
} }];
